package cn.zhuatech.marketingautomation.deep;import cn.zhuatech.marketingautomation.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/marketing-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/audiences")ApiResponse<?> audience(@Valid @RequestBody DeepDomainService.AudienceRequest r){return ApiResponse.ok(s.audience(r));}@PostMapping("/campaigns")ApiResponse<?> campaign(@Valid @RequestBody DeepDomainService.CampaignRequest r){return ApiResponse.ok(s.campaign(r));}@PostMapping("/campaigns/{id}/journeys")ApiResponse<?> journey(@PathVariable Long id,@Valid @RequestBody DeepDomainService.JourneyRequest r){return ApiResponse.ok(s.journey(id,r));}@PostMapping("/campaigns/{id}/launch")ApiResponse<?> launch(@PathVariable Long id){return ApiResponse.ok(s.launch(id));}@PostMapping("/consents")ApiResponse<?> consent(@Valid @RequestBody DeepDomainService.ConsentRequest r){return ApiResponse.ok(s.consent(r));}@PostMapping("/consents/{id}/revoke")ApiResponse<?> revoke(@PathVariable Long id){return ApiResponse.ok(s.revoke(id));}@PostMapping("/campaigns/{id}/touch-events")ApiResponse<?> touch(@PathVariable Long id,@Valid @RequestBody DeepDomainService.TouchRequest r){return ApiResponse.ok(s.touch(id,r));}}
